sed -i 's/socket.connect(InetSocketAddress(HOST_ADDRESS, HOST_PORT), 10000)/            var targetAddress = HOST_ADDRESS\n            val linkProperties = connectivityManager.getLinkProperties(network)\n            if (linkProperties != null) {\n                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.R) {\n                    linkProperties.dhcpServerAddress?.let { targetAddress = it.hostAddress ?: targetAddress }\n                }\n                if (targetAddress == HOST_ADDRESS) {\n                    for (route in linkProperties.routes) {\n                        if (route.hasGateway() \&\& route.gateway != null) {\n                            targetAddress = route.gateway!!.hostAddress ?: HOST_ADDRESS\n                            break\n                        }\n                    }\n                }\n            }\n            Log.d(TAG, "Resolved host IP: $targetAddress")\n            socket.connect(InetSocketAddress(targetAddress, HOST_PORT), 10000)/' composeApp/src/androidMain/kotlin/com/peersync/app/network/WifiSocketController.kt
